+		"created", "claimed", "rag_pre_flight", "started",
+		"reviewer_started", "fix_started", "work_phase_complete",
+		"review_blocked", "retried", "done", "blocked",
+		"reviewer_complete", "ready", "cancelled",
+	}
+	activity := make([]database.WorkspaceActivityEvent, 0, len(allActions))
+	for _, a := range allActions {
+		activity = append(activity, makeActivity(a))
+	}
+	db := &fakeDB{workspaces: []database.Workspace{ws}, activity: activity}
